namespace App.Application.DependencyInjection;

public static class ApplicationServiceCollectionExtensions
{
    public static IServiceCollection AddApplication(this IServiceCollection services)
    {
        // IPatientService / PatientService：维护患者资料；使用 Scoped，保证一次请求共享同一工作单元。
        services.AddScoped<IPatientService, PatientService>();
        // IPatientDemographicOptionResolver：把患者性别解析为业务选项，患者资料维护与接诊共用。

        // Scoped：生命周期必须与当前请求的工作单元一致。
        services.AddScoped<IPatientDemographicOptionResolver, PatientDemographicOptionResolver>();
        // ITaskProgressEventChannel / TaskProgressEventChannel：提供进程内任务进度广播；使用 Singleton，保证线程安全事件通道被共享。
        services.AddSingleton<ITaskProgressEventChannel, TaskProgressEventChannel>();
        // 无状态格式化器：提供金额格式化；Transient 无状态，每次取新实例。
        services
            .AddTransient<IMoneyFormatter, MoneyFormatter>();
        services.AddScoped<RegistrationOrderInfoSourceHandler>();
        services.AddScoped<IOrderInfoSourceHandler>(provider => provider.GetRequiredService<RegistrationOrderInfoSourceHandler>());
        // services.AddScoped<ICommentedService, CommentedService>();
        services.AddScoped<IDepartmentService, DepartmentService>(); // 维护科室；Scoped 保证一次请求
        services.AddScoped<IStaffMemberService, StaffMemberService>();
        // IClinicProfileService / ClinicProfileService：维护诊所资料。
        services.AddScoped<IClinicProfileService, ClinicProfileService>();
        // ITimeSource / TimeSource：提供系统时钟；使用 Scoped，保证一次请求内时间一致。
        services.AddSingleton<ITimeSource, TimeSource>();
        return services;
    }
}

